-- P3 mylife-app: the MyLife diabetes diary's data in the shared Supabase project.
--
-- The Flutter app (mylife.alnyron.dk) keeps its in-memory store and loads the signed-in user's
-- rows at login, then writes through to these two tables. mylife_profile holds one settings row
-- per user; mylife_events holds the diary events. Ids are generated by the app (no default).
-- Additive: no existing table, policy or data changes.
--
-- Decimals are exact BigInt-rational strings in the app, so they are stored as text (hypo, hyper,
-- value) or inside jsonb as strings (calc segments), never float or numeric: a round trip must
-- give back the same string the frozen calc code wrote.
--
-- Health data: strict per-user RLS. Every policy is `(select auth.uid()) = user_id`, evaluated
-- once per statement (initPlan), for `authenticated` only. anon has no grant and no policy.
-- Supabase's default privileges grant ALL on new public tables to anon and authenticated, which
-- includes TRUNCATE (not subject to RLS), so both are revoked before the explicit grants.
-- updated_at is kept current by private.set_updated_at() like every other table (core 0100).

-- Tables ------------------------------------------------------------------------------------
-- mylife_profile: one row per user (singleton settings). Decimals as TEXT (exact).
create table if not exists public.mylife_profile (
  user_id    uuid primary key references auth.users (id) on delete cascade,
  name       text,
  unit       text not null default 'mgdl' check (unit in ('mgdl', 'mmol')),
  hypo       text not null default '70',
  hyper      text not null default '180',
  calc       jsonb not null default '{}'::jsonb,
  updated_at timestamptz not null default now()
);
create trigger mylife_profile_updated_at before update on public.mylife_profile
  for each row execute function private.set_updated_at();

-- mylife_events: diary events. value is a decimal-as-string or free text; info/markers flexible.
create table if not exists public.mylife_events (
  id            uuid primary key,
  user_id       uuid not null references auth.users (id) on delete cascade,
  utc_ms        bigint not null,
  type          int not null,
  value         text,
  info          jsonb not null default '{}'::jsonb,
  comment       text,
  markers       text[] not null default '{}',
  manual        boolean not null default true,
  deleted       boolean not null default false,
  bg_value_type int not null default 0,
  not_for_iob   boolean not null default false,
  updated_at    timestamptz not null default now()
);
create index if not exists mylife_events_user_utc_idx on public.mylife_events (user_id, utc_ms desc);
create index if not exists mylife_events_user_type_idx on public.mylife_events (user_id, type);
create trigger mylife_events_updated_at before update on public.mylife_events
  for each row execute function private.set_updated_at();

alter table public.mylife_profile enable row level security;
alter table public.mylife_events  enable row level security;

-- Grants ------------------------------------------------------------------------------------
revoke all on table public.mylife_profile, public.mylife_events from anon, authenticated;
grant select, insert, update, delete on public.mylife_profile to authenticated;
grant select, insert, update, delete on public.mylife_events to authenticated;

-- Policies: each user reads and writes only their own rows -----------------------------------
create policy mylife_profile_select on public.mylife_profile for select to authenticated
  using ((select auth.uid()) = user_id);
create policy mylife_profile_insert on public.mylife_profile for insert to authenticated
  with check ((select auth.uid()) = user_id);
create policy mylife_profile_update on public.mylife_profile for update to authenticated
  using ((select auth.uid()) = user_id) with check ((select auth.uid()) = user_id);
create policy mylife_profile_delete on public.mylife_profile for delete to authenticated
  using ((select auth.uid()) = user_id);

create policy mylife_events_select on public.mylife_events for select to authenticated
  using ((select auth.uid()) = user_id);
create policy mylife_events_insert on public.mylife_events for insert to authenticated
  with check ((select auth.uid()) = user_id);
create policy mylife_events_update on public.mylife_events for update to authenticated
  using ((select auth.uid()) = user_id) with check ((select auth.uid()) = user_id);
create policy mylife_events_delete on public.mylife_events for delete to authenticated
  using ((select auth.uid()) = user_id);
